parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "status": {
      "type": "boolean",
      "description": "true — ответ найден в базе, false — не найден"
    },
    "answer": {
      "type": "string",
      "description": "текст ответа сотруднику или пояснение причины"
    },
    "source": {
      "type": "string",
      "description": "источник (документ/раздел), пустая строка если status=false"
    }
  },
  "required": ["status", "answer", "source"]
}
